CREATE OR REPLACE FUNCTION public.admin_cleanup_yorp_sample_dataset(_session_token text, _batch_name text DEFAULT 'PCYDO-YORP-2024-2026'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
DECLARE
  _admin_id uuid;
  _org_ids uuid[] := '{}';
  _user_ids uuid[] := '{}';
  _deleted_orgs integer := 0;
  _deleted_budgets integer := 0;
  _deleted_liquidations integer := 0;
  _deleted_users integer := 0;
  _required_documents integer := 0;
  _mapped_assets integer := 0;
  _now timestamptz := clock_timestamp();
BEGIN
  SELECT vat.admin_id INTO _admin_id
  FROM public.validate_admin_session_token(_session_token) vat LIMIT 1;
  IF _admin_id IS NULL THEN RAISE EXCEPTION 'Admin account is not authorized.'; END IF;
  IF NOT public.is_development_or_test_environment() THEN
    RAISE EXCEPTION 'Cleanup is available only in an explicitly configured non-production environment.';
  END IF;
  IF _batch_name IS DISTINCT FROM 'PCYDO-YORP-2024-2026' THEN
    RAISE EXCEPTION 'Cleanup is restricted to batch PCYDO-YORP-2024-2026.';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('PCYDO-YORP-2024-2026'));

  SELECT coalesce(array_agg(id), '{}'), coalesce(array_agg(user_id), '{}')
  INTO _org_ids, _user_ids
  FROM public.organization_profiles
  WHERE is_seeded_sample_data IS TRUE
    AND seed_batch = _batch_name
    AND id <> '8170959f-2bb8-40ea-8ce8-31deb514de17'::uuid
    AND coalesce(is_renewal_test_account, false) IS FALSE;

  SELECT coalesce(array_agg(DISTINCT op.user_id) FILTER (WHERE op.user_id IS NOT NULL), '{}')
  INTO _user_ids
  FROM public.organization_profiles op
  WHERE op.id = ANY(_org_ids)
    AND NOT EXISTS (
      SELECT 1 FROM public.organization_profiles renewal
      WHERE renewal.user_id = op.user_id
        AND (renewal.id = '8170959f-2bb8-40ea-8ce8-31deb514de17'::uuid
          OR coalesce(renewal.is_renewal_test_account, false) IS TRUE)
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.organization_profiles related
      WHERE related.user_id = op.user_id
        AND related.id <> ALL(_org_ids)
    );

  IF cardinality(_org_ids) > 0 THEN
    SELECT count(*) INTO _required_documents
    FROM public.required_document_types rdt
    WHERE rdt.is_active IS TRUE AND coalesce(rdt.is_required, true) IS TRUE
      AND coalesce(rdt.template_scope, 'document_submission') = 'document_submission'
      AND (rdt.scope IS NULL OR rdt.scope IN ('registration', 'both'))
      AND (rdt.template_category IS NULL OR rdt.template_category = '{}' OR 'yorp' = ANY(rdt.template_category));
    SELECT count(*) INTO _mapped_assets
    FROM public.required_document_types rdt
    JOIN public.yorp_sample_document_assets asset ON asset.document_type_id = rdt.id
    JOIN storage.objects object_row ON object_row.bucket_id = asset.bucket_id AND object_row.name = asset.object_name
    WHERE rdt.is_active IS TRUE AND coalesce(rdt.is_required, true) IS TRUE
      AND coalesce(rdt.template_scope, 'document_submission') = 'document_submission'
      AND (rdt.scope IS NULL OR rdt.scope IN ('registration', 'both'))
      AND (rdt.template_category IS NULL OR rdt.template_category = '{}' OR 'yorp' = ANY(rdt.template_category));
    IF _required_documents = 0 OR _mapped_assets <> _required_documents THEN
      RAISE EXCEPTION 'Cleanup stopped because reusable registration seed assets are not mapped for every active YORP requirement. Map % of % requirements before cleanup.', _mapped_assets, _required_documents;
    END IF;

    IF EXISTS (SELECT 1 FROM public.ypop_entries WHERE organization_id = ANY(_org_ids)) THEN
      RAISE EXCEPTION 'Cleanup stopped: seeded organizations have YPOP entries that are not part of the authoritative fixture and would otherwise cascade-delete.';
    END IF;
    IF EXISTS (SELECT 1 FROM public.organization_renewals WHERE organization_id = ANY(_org_ids)) THEN
      RAISE EXCEPTION 'Cleanup stopped: seeded organizations have renewal history that this fixture cannot reconstruct.';
    END IF;
    IF EXISTS (SELECT 1 FROM public.inquiries WHERE organization_id = ANY(_org_ids)) THEN
      RAISE EXCEPTION 'Cleanup stopped: seeded organizations have inquiry records outside the generated fixture.';
    END IF;
    IF EXISTS (SELECT 1 FROM public.compliance_remarks WHERE organization_id = ANY(_org_ids)) THEN
      RAISE EXCEPTION 'Cleanup stopped: seeded organizations have compliance history outside the generated fixture.';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.budget_requests
      WHERE organization_id = ANY(_org_ids)
        AND (is_seeded_sample_data IS DISTINCT FROM TRUE OR seed_batch IS DISTINCT FROM _batch_name)
    ) THEN
      RAISE EXCEPTION 'Cleanup stopped: one or more seeded organizations have budget requests outside the generated fixture.';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.liquidation_reports
      WHERE organization_id = ANY(_org_ids)
        AND (is_seeded_sample_data IS DISTINCT FROM TRUE OR seed_batch IS DISTINCT FROM _batch_name)
    ) THEN
      RAISE EXCEPTION 'Cleanup stopped: one or more seeded organizations have liquidation records outside the generated fixture.';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.document_submissions ds
      WHERE ds.organization_id = ANY(_org_ids)
        AND (ds.is_seeded_sample_data IS DISTINCT FROM TRUE OR ds.seed_batch IS DISTINCT FROM _batch_name)
    ) THEN
      RAISE EXCEPTION 'Cleanup stopped: one or more seeded organizations have registration packets not tracked as generated fixture data.';
    END IF;

    PERFORM set_config('app.allow_org_deletion', 'true', true);
    UPDATE public.organization_profiles
      SET current_accreditation_id = NULL
      WHERE id = ANY(_org_ids)
        AND id <> '8170959f-2bb8-40ea-8ce8-31deb514de17'::uuid
        AND coalesce(is_renewal_test_account, false) IS FALSE;

    WITH deleted AS (
      DELETE FROM public.liquidation_reports
      WHERE organization_id = ANY(_org_ids)
        AND is_seeded_sample_data IS TRUE AND seed_batch = _batch_name
      RETURNING id
    ) SELECT count(*) INTO _deleted_liquidations FROM deleted;

    WITH deleted AS (
      DELETE FROM public.budget_requests
      WHERE organization_id = ANY(_org_ids)
        AND is_seeded_sample_data IS TRUE AND seed_batch = _batch_name
      RETURNING id
    ) SELECT count(*) INTO _deleted_budgets FROM deleted;

    DELETE FROM public.organization_contacts WHERE organization_id = ANY(_org_ids);
    DELETE FROM public.organization_accreditations WHERE organization_id = ANY(_org_ids);
    DELETE FROM public.notifications
    WHERE organization_id = ANY(_org_ids) OR user_id = ANY(_user_ids);

    -- Preserve organization-linked audit history while clearing the cascading FK.
    UPDATE public.activity_logs
      SET organization_id = NULL
      WHERE organization_id = ANY(_org_ids);

    WITH deleted AS (
      DELETE FROM public.organization_profiles
      WHERE id = ANY(_org_ids)
        AND is_seeded_sample_data IS TRUE
        AND seed_batch = _batch_name
        AND id <> '8170959f-2bb8-40ea-8ce8-31deb514de17'::uuid
        AND coalesce(is_renewal_test_account, false) IS FALSE
      RETURNING id
    ) SELECT count(*) INTO _deleted_orgs FROM deleted;

    DELETE FROM public.user_profiles WHERE user_id = ANY(_user_ids);
    DELETE FROM auth.identities WHERE user_id = ANY(_user_ids)
      AND user_id <> ALL(ARRAY(
        SELECT renewal.user_id FROM public.organization_profiles renewal
        WHERE renewal.user_id IS NOT NULL
          AND (renewal.id = '8170959f-2bb8-40ea-8ce8-31deb514de17'::uuid
            OR coalesce(renewal.is_renewal_test_account, false) IS TRUE)
      ));
    WITH deleted AS (
      DELETE FROM auth.users WHERE id = ANY(_user_ids)
        AND id <> ALL(ARRAY(
          SELECT renewal.user_id FROM public.organization_profiles renewal
          WHERE renewal.user_id IS NOT NULL
            AND (renewal.id = '8170959f-2bb8-40ea-8ce8-31deb514de17'::uuid
              OR coalesce(renewal.is_renewal_test_account, false) IS TRUE)
        ))
      RETURNING id
    ) SELECT count(*) INTO _deleted_users FROM deleted;
  END IF;

  INSERT INTO public.activity_logs(actor_user_id, action, related_type, description, created_at)
  VALUES (_admin_id, 'cleaned_yorp_sample_dataset', 'system_batch',
    format('Removed generated PCYDO YORP fixture records: %s organizations, %s budgets, %s liquidations, %s test identities. Reusable Storage seed assets were retained.',
      _deleted_orgs, _deleted_budgets, _deleted_liquidations, _deleted_users), _now);

  RETURN jsonb_build_object(
    'success', true, 'batch_name', _batch_name,
    'deleted_organizations', _deleted_orgs,
    'deleted_budget_requests', _deleted_budgets,
    'deleted_liquidations', _deleted_liquidations,
    'deleted_users', _deleted_users,
    'storage_seed_assets_deleted', 0,
    'renewal_test_organization_excluded', true,
    'timestamp', _now
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_restore_renewal_test_scenario(p_session_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
DECLARE
  _admin_id uuid;
  _org record;
  _acc record;
  _restored_end_date date;
  _today date := current_date;
BEGIN
  SELECT vat.admin_id INTO _admin_id
  FROM public.validate_admin_session_token(p_session_token) vat
  LIMIT 1;

  IF _admin_id IS NULL THEN
    RAISE EXCEPTION 'Admin account is not authorized.';
  END IF;

  IF NOT public.is_development_or_test_environment() THEN
    RAISE EXCEPTION 'Renewal Test Environment is disabled in production.';
  END IF;

  SELECT * INTO _org
  FROM public.organization_profiles
  WHERE is_renewal_test_account = true
     OR organization_email = 'renewal.test@pasigcity.gov.ph'
  LIMIT 1;

  IF _org.id IS NULL THEN
    RAISE EXCEPTION 'Renewal Test Organization does not exist.';
  END IF;

  PERFORM set_config('app.allow_test_scenario_prep', 'true', true);

  SELECT * INTO _acc
  FROM public.organization_accreditations
  WHERE organization_id = _org.id
    AND status = 'active'
  ORDER BY term_number DESC
  LIMIT 1
  FOR UPDATE;

  IF _acc.id IS NOT NULL THEN
    _restored_end_date := (_acc.start_date + interval '3 years')::date;

    UPDATE public.organization_accreditations
    SET end_date = _restored_end_date
    WHERE id = _acc.id;

    UPDATE public.organization_profiles
    SET accreditation_expires_at = _restored_end_date::timestamptz
    WHERE id = _org.id;
  END IF;

  INSERT INTO public.activity_logs (
    actor_user_id,
    organization_id,
    action,
    related_type,
    related_id,
    description
  ) VALUES (
    _admin_id,
    _org.id,
    'restored_renewal_test_scenario',
    'organization',
    _org.id,
    'Restored renewal test scenario to default 3-year term.'
  );

  RETURN jsonb_build_object(
    'success', true,
    'organizationId', _org.id,
    'endDate', _restored_end_date,
    'derivedStatus', public.derive_accreditation_status('active', _restored_end_date, _today)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_organization_renewal_eligibility(_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
DECLARE
  _today date := current_date;
  _org record;
  _acc record;
  _end_date date;
  _days_diff integer;
  _window_status text;
  _can_draft boolean;
  _can_submit boolean;
  _days_until_open integer := NULL;
  _days_past_expiry integer := NULL;
  _reason text;
BEGIN
  SELECT * INTO _org
  FROM public.organization_profiles
  WHERE id = _org_id;

  IF _org.id IS NULL THEN
    RETURN jsonb_build_object(
      'canDraft', false,
      'canSubmit', false,
      'windowStatus', 'too_early',
      'reason', 'Organization profile not found.',
      'daysRemaining', NULL,
      'daysUntilOpen', NULL,
      'daysPastExpiry', NULL,
      'expiresAt', NULL
    );
  END IF;

  -- Resolve authoritative active accreditation term
  SELECT * INTO _acc
  FROM public.organization_accreditations
  WHERE organization_id = _org_id
    AND status = 'active'
  ORDER BY term_number DESC
  LIMIT 1;

  IF _acc.id IS NULL THEN
    IF _org.accreditation_expires_at IS NOT NULL THEN
      _end_date := _org.accreditation_expires_at::date;
    ELSE
      RETURN jsonb_build_object(
        'canDraft', false,
        'canSubmit', false,
        'windowStatus', 'too_early',
        'reason', 'No authoritative accreditation expiration date found.',
        'daysRemaining', NULL,
        'daysUntilOpen', NULL,
        'daysPastExpiry', NULL,
        'expiresAt', NULL
      );
    END IF;
  ELSE
    _end_date := _acc.end_date;
  END IF;

  _days_diff := _end_date - _today;

  -- Authoritative Window Rules:
  -- 1. Window opens: 90 calendar days before expiry
  -- 2. Active Window: [end_date - 90, end_date]
  -- 3. Late Renewal (Grace Period): (end_date, end_date + 180]
  -- 4. Cutoff exceeded (Lapsed): > 180 days past expiry
  IF _days_diff > 90 THEN
    _window_status := 'too_early';
    _can_draft := false;
    _can_submit := false;
    _days_until_open := _days_diff - 90;
    _reason := format('Renewal window opens 90 days before expiry (in %s days).', _days_until_open);
  ELSIF _days_diff >= 0 THEN
    _window_status := 'open';
    _can_draft := true;
    _can_submit := true;
    _reason := 'Renewal window is open.';
  ELSIF ABS(_days_diff) <= 180 THEN
    _window_status := 'expired';
    _can_draft := true;
    _can_submit := true;
    _days_past_expiry := ABS(_days_diff);
    _reason := format('Late renewal allowed within 180 days of expiry (%s days expired).', _days_past_expiry);
  ELSE
    _window_status := 'lapsed';
    _can_draft := false;
    _can_submit := false;
    _days_past_expiry := ABS(_days_diff);
    _reason := 'Late renewal window expired (180 days past expiry). Full re-registration is required.';
  END IF;

  RETURN jsonb_build_object(
    'canDraft', _can_draft,
    'canSubmit', _can_submit,
    'windowStatus', _window_status,
    'daysRemaining', GREATEST(0, _days_diff),
    'daysUntilOpen', _days_until_open,
    'daysPastExpiry', _days_past_expiry,
    'expiresAt', _end_date,
    'reason', _reason
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_organization_account_canonical(_session_token text, _organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  _admin_id uuid;
  _org public.organization_profiles%rowtype;
  _user_id uuid;
begin
  -- 1. Authorize admin caller
  select vat.admin_id into _admin_id
  from public.validate_admin_session_token(_session_token) vat
  limit 1;

  if _admin_id is null then
    return jsonb_build_object(
      'success', false,
      'stage', 'authorization',
      'error', 'You are not authorized to delete organization accounts.'
    );
  end if;

  -- 2. Lock and load target organization profile
  select * into _org
  from public.organization_profiles
  where id = _organization_id
  for update;

  if not found then
    return jsonb_build_object(
      'success', false,
      'already_deleted', true,
      'stage', 'validation',
      'error', 'Organization profile not found or already deleted.'
    );
  end if;

  _user_id := _org.user_id;

  -- 3. Protection checks: verify target is not an administrator or super admin
  if exists (
    select 1 from public.admin_accounts where lower(trim(email)) = lower(trim(_org.organization_email))
  ) or (_user_id is not null and exists (
    select 1 from public.admin_accounts where id = _user_id
  )) or (_user_id is not null and exists (
    select 1 from public.user_roles ur
    join public.roles r on r.id = ur.role_id
    where ur.user_id = _user_id and r.code::text in ('admin', 'super_admin')
  )) then
    return jsonb_build_object(
      'success', false,
      'is_protected', true,
      'stage', 'protection_check',
      'error', 'Administrator accounts cannot be deleted from the YORP Registry.'
    );
  end if;

  perform ytrace_identity.authorize_reviewer(_session_token);
  if ytrace_identity.has_retained_history(_organization_id) then
    raise exception 'Official organization history is retained. Request an authorized archival/retention review before permanent deletion.';
  end if;

  -- 4. Activate transaction-local bypass for immutability triggers
  perform set_config('app.allow_org_deletion', 'true', true);

  -- 5. Disassociate and clean direct Auth dependencies
  if _user_id is not null then
    -- Nullify submitted_by on YPOP to preserve organization historical context without blocking FK
    update public.ypop_entries
    set submitted_by = null
    where submitted_by = _user_id;

    update public.ypop_event_participations
    set submitted_by = null
    where submitted_by = _user_id;

    update public.ypop_org_activities
    set submitted_by = null
    where submitted_by = _user_id;

    -- Clean user specific auxiliary records
    delete from public.user_policy_acceptance where user_id = _user_id;
    delete from public.user_roles where user_id = _user_id;
    delete from public.user_profiles where user_id = _user_id;
  end if;

  -- 6. Clean accreditation and renewal hierarchies safely
  update public.organization_renewals
  set current_accreditation_id = null
  where organization_id = _organization_id;

  delete from public.organization_renewals
  where organization_id = _organization_id;

  delete from public.organization_accreditations
  where organization_id = _organization_id;

  -- 7. Clean document submissions, budget requests, and liquidations
  delete from public.document_submission_files
  where submission_id in (select id from public.document_submissions where organization_id = _organization_id);

  delete from public.document_submissions
  where organization_id = _organization_id;

  delete from public.budget_request_files
  where budget_request_id in (select id from public.budget_requests where organization_id = _organization_id);

  delete from public.budget_requests
  where organization_id = _organization_id;

  delete from public.liquidation_report_files
  where liquidation_report_id in (select id from public.liquidation_reports where organization_id = _organization_id);

  delete from public.liquidation_reports
  where organization_id = _organization_id;

  -- 8. Clean move applications, URN history, and YPOP organization activities
  delete from public.move_files where organization_id = _organization_id;
  delete from public.move_applications where organization_id = _organization_id;
  delete from public.urn_review_history where organization_id = _organization_id;

  delete from public.ypop_files where organization_id = _organization_id;
  delete from public.ypop_event_files where organization_id = _organization_id;
  delete from public.ypop_org_activity_files where organization_id = _organization_id;
  delete from public.ypop_org_activities where organization_id = _organization_id;
  delete from public.ypop_event_participations where organization_id = _organization_id;
  delete from public.ypop_entries where organization_id = _organization_id;

  -- 9. Clean notifications, compliance remarks, inquiries
  delete from public.notifications where organization_id = _organization_id;
  delete from public.compliance_remarks where organization_id = _organization_id;
  delete from public.inquiries where organization_id = _organization_id;

  -- 10. Disassociate historical activity logs without deleting audit trail
  update public.activity_logs
  set organization_id = null
  where organization_id = _organization_id;

  -- 11. Delete organization profile
  delete from public.organization_profiles
  where id = _organization_id;

  -- 12. Verify organization profile is removed
  if exists (select 1 from public.organization_profiles where id = _organization_id) then
    raise exception 'Database deletion failed: organization_profiles row could not be removed.';
  end if;

  return jsonb_build_object(
    'success', true,
    'organization_id', _org.id,
    'organization_name', _org.organization_name,
    'organization_email', _org.organization_email,
    'user_id', _user_id,
    'urn', _org.urn
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_accreditation_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF tg_op = 'UPDATE' THEN
    IF old.term_number IS DISTINCT FROM new.term_number
       OR old.start_date IS DISTINCT FROM new.start_date
       OR old.end_date IS DISTINCT FROM new.end_date
       OR old.certificate_urn IS DISTINCT FROM new.certificate_urn
       OR old.approved_by IS DISTINCT FROM new.approved_by
       OR old.approved_at IS DISTINCT FROM new.approved_at
       OR old.created_at IS DISTINCT FROM new.created_at
       OR old.is_legacy_inferred IS DISTINCT FROM new.is_legacy_inferred THEN
      -- Controlled exception: permit date adjustments strictly for the designated renewal test account in non-production
      IF current_setting('app.allow_test_scenario_prep', true) = 'true' THEN
        IF EXISTS (
          SELECT 1 FROM public.organization_profiles op
          WHERE op.id = old.organization_id
            AND (op.is_renewal_test_account = true OR op.organization_email = 'renewal.test@pasigcity.gov.ph')
        ) THEN
          RETURN new;
        END IF;
      END IF;

      RAISE EXCEPTION 'Historical accreditation term fields are immutable.';
    END IF;

    -- Revocation immutability rules:
    IF old.revoked_at IS NOT NULL AND new.revoked_at IS DISTINCT FROM old.revoked_at THEN
      RAISE EXCEPTION 'Accreditation revocation timestamp is immutable once set.';
    END IF;

    IF old.revocation_reason IS NOT NULL AND new.revocation_reason IS DISTINCT FROM old.revocation_reason THEN
      RAISE EXCEPTION 'Accreditation revocation reason is immutable once set.';
    END IF;

    IF new.status <> 'revoked' AND new.revoked_at IS NOT NULL THEN
      RAISE EXCEPTION 'Non-revoked accreditation terms cannot have a revocation timestamp.';
    END IF;

    -- Valid status transitions only:
    IF old.status = 'superseded' AND new.status <> 'superseded' THEN
      IF current_setting('app.allow_test_scenario_prep', true) = 'true' THEN
        IF EXISTS (
          SELECT 1 FROM public.organization_profiles op
          WHERE op.id = old.organization_id
            AND (op.is_renewal_test_account = true OR op.organization_email = 'renewal.test@pasigcity.gov.ph')
        ) THEN
          RETURN new;
        END IF;
      END IF;
      RAISE EXCEPTION 'A superseded accreditation term cannot be reactivated or altered.';
    END IF;

    IF old.status = 'revoked' AND new.status <> 'revoked' THEN
      RAISE EXCEPTION 'A revoked accreditation term cannot be reactivated.';
    END IF;

    IF old.status <> 'revoked' AND new.status = 'revoked' THEN
      IF new.revoked_at IS NULL THEN
        new.revoked_at := clock_timestamp();
      END IF;
    END IF;

    RETURN new;
  END IF;

  IF tg_op = 'DELETE' THEN
    IF current_setting('app.allow_org_deletion', true) = 'true' THEN
      RETURN old;
    END IF;
    IF current_setting('app.allow_test_scenario_prep', true) = 'true' THEN
      IF EXISTS (
        SELECT 1 FROM public.organization_profiles op
        WHERE op.id = old.organization_id
          AND (op.is_renewal_test_account = true OR op.organization_email = 'renewal.test@pasigcity.gov.ph')
      ) THEN
        RETURN old;
      END IF;
    END IF;
    RAISE EXCEPTION 'Accreditation terms in the authoritative ledger cannot be deleted.';
  END IF;

  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_renewal_terminal_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF tg_op = 'UPDATE' THEN
    IF old.status IN ('approved', 'rejected') THEN
      IF current_setting('app.allow_test_scenario_prep', true) = 'true' THEN
        IF EXISTS (
          SELECT 1 FROM public.organization_profiles op
          WHERE op.id = old.organization_id
            AND (op.is_renewal_test_account = true OR op.organization_email = 'renewal.test@pasigcity.gov.ph')
        ) THEN
          RETURN new;
        END IF;
      END IF;
      RAISE EXCEPTION 'Terminal renewal records cannot be modified.';
    END IF;
    RETURN new;
  END IF;

  IF tg_op = 'DELETE' THEN
    IF current_setting('app.allow_org_deletion', true) = 'true' THEN
      RETURN old;
    END IF;
    IF current_setting('app.allow_test_scenario_prep', true) = 'true' THEN
      IF EXISTS (
        SELECT 1 FROM public.organization_profiles op
        WHERE op.id = old.organization_id
          AND (op.is_renewal_test_account = true OR op.organization_email = 'renewal.test@pasigcity.gov.ph')
      ) THEN
        RETURN old;
      END IF;
    END IF;
    IF old.status IN ('approved', 'rejected') THEN
      RAISE EXCEPTION 'Terminal renewal records cannot be deleted.';
    END IF;
    RETURN old;
  END IF;

  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_submitted_registration_document_edits()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  _submission_status text;
  _registration_submission boolean;
begin
  -- Admin and correction RPCs run with their validated definer privileges.
  if current_user not in ('authenticated', 'anon')
     or public.current_user_is_admin() then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  select ds.status,
         ds.submission_scope = 'registration' and ds.renewal_id is null
    into _submission_status, _registration_submission
  from public.document_submissions ds
  where ds.id = old.submission_id
  for update;

  if old.admin_status is distinct from 'draft'
     or _submission_status is null
     or not (
       _submission_status in ('draft', 'needs_revision')
       or (
         _registration_submission is true
         and _submission_status in ('under_admin_review', 'submitted', 'ready_for_review')
       )
     ) then
    raise exception 'Submitted documents are locked. Only draft documents can be edited or removed; requested revisions must use the replacement flow.';
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.is_development_or_test_environment()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  _env text;
BEGIN
  SELECT coalesce(value_json->>'environment', value_json::text)
  INTO _env
  FROM public.admin_system_settings
  WHERE setting_key = 'general.environment'
  LIMIT 1;

  -- Strict check: reject null, unknown, unset, or production environments
  IF _env IS NULL THEN
    RETURN false;
  END IF;

  _env := lower(trim(_env, '" '));
  RETURN _env IN ('development', 'dev', 'test', 'testing', 'staging', 'local');
END;
$function$

CREATE OR REPLACE FUNCTION public.rebalance_yorp_seed_reporting_quarters()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  _row record;
  _activity date;
  _release timestamptz;
  _before jsonb;
  _after jsonb;
  _reports_before jsonb;
  _reports_after jsonb;
  _org_count integer;
  _budget_count integer;
  _missing integer;
  _terminal_definition text;
  _terminal_anchor text := 'OR NEW.release_date IS DISTINCT FROM OLD.release_date';
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('PCYDO-YORP-2024-2026'));
  LOCK TABLE public.budget_requests, public.liquidation_reports IN SHARE ROW EXCLUSIVE MODE;
  SELECT count(*) INTO _org_count FROM public.organization_profiles op
  WHERE op.is_seeded_sample_data IS TRUE AND op.seed_batch='PCYDO-YORP-2024-2026'
    AND op.id <> '8170959f-2bb8-40ea-8ce8-31deb514de17'::uuid
    AND coalesce(op.is_renewal_test_account,false) IS FALSE
    AND op.seed_source_year IN (2024,2025,2026) AND op.seed_source_record_number IS NOT NULL;
  SELECT count(*), jsonb_agg(jsonb_build_array(br.id,br.organization_id,br.status,br.requested_amount,br.approved_amount,br.released_amount) ORDER BY br.id)
    INTO _budget_count,_before
  FROM public.budget_requests br JOIN public.organization_profiles op ON op.id=br.organization_id
  WHERE br.is_seeded_sample_data IS TRUE AND br.seed_batch='PCYDO-YORP-2024-2026'
    AND op.is_seeded_sample_data IS TRUE AND op.seed_batch=br.seed_batch
    AND op.id <> '8170959f-2bb8-40ea-8ce8-31deb514de17'::uuid
    AND coalesce(op.is_renewal_test_account,false) IS FALSE;
  IF _org_count <> 84 OR _budget_count <> 84 THEN
    RAISE EXCEPTION 'Unexpected PCYDO fixture size: organizations %, budgets %',_org_count,_budget_count;
  END IF;
  IF EXISTS (SELECT 1 FROM public.liquidation_reports lr JOIN public.budget_requests br ON br.id=lr.budget_request_id
    WHERE br.is_seeded_sample_data IS TRUE AND br.seed_batch='PCYDO-YORP-2024-2026'
      AND (coalesce(lr.is_seeded_sample_data,false) IS FALSE OR lr.seed_batch IS DISTINCT FROM br.seed_batch)) THEN
    RAISE EXCEPTION 'Seed budgets have unmarked liquidation reports; automatic date repair stopped';
  END IF;
  SELECT jsonb_agg(jsonb_build_array(lr.id,lr.budget_request_id,lr.organization_id,lr.status) ORDER BY lr.id) INTO _reports_before
  FROM public.liquidation_reports lr JOIN public.organization_profiles op ON op.id=lr.organization_id
  WHERE lr.is_seeded_sample_data IS TRUE AND lr.seed_batch='PCYDO-YORP-2024-2026'
    AND op.is_seeded_sample_data IS TRUE AND op.seed_batch=lr.seed_batch
    AND op.id <> '8170959f-2bb8-40ea-8ce8-31deb514de17'::uuid
    AND coalesce(op.is_renewal_test_account,false) IS FALSE;

  -- Only this privileged, transaction-scoped fixture repair may adjust a release
  -- date. Concurrent writes are locked out; amounts/status guards stay active.
  -- Restore the exact original definition before returning. Any failure rolls
  -- back both the function change and all row updates atomically.
  _terminal_definition := pg_get_functiondef('public.enforce_budget_request_terminal_status()'::regprocedure);
  IF strpos(_terminal_definition,_terminal_anchor)=0 THEN
    RAISE EXCEPTION 'Unexpected terminal release guard shape';
  END IF;
  EXECUTE replace(_terminal_definition,_terminal_anchor,
    'OR (NEW.release_date IS DISTINCT FROM OLD.release_date AND NOT (
      OLD.is_seeded_sample_data IS TRUE AND NEW.is_seeded_sample_data IS TRUE
      AND OLD.seed_batch = ''PCYDO-YORP-2024-2026''
      AND NEW.seed_batch = ''PCYDO-YORP-2024-2026''
      AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id
    ))');

  FOR _row IN
    SELECT br.id,br.organization_id,op.seed_source_year AS year,
      CASE WHEN op.seed_source_year=2026 THEN 1 ELSE
        ((row_number() OVER (PARTITION BY op.seed_source_year,br.status ORDER BY op.seed_source_record_number,br.id)-1)%4+1)::integer END AS quarter,
      op.seed_source_record_number AS ordinal
    FROM public.budget_requests br JOIN public.organization_profiles op ON op.id=br.organization_id
    WHERE br.is_seeded_sample_data IS TRUE AND br.seed_batch='PCYDO-YORP-2024-2026'
      AND op.is_seeded_sample_data IS TRUE AND op.seed_batch=br.seed_batch
      AND op.id <> '8170959f-2bb8-40ea-8ce8-31deb514de17'::uuid
      AND coalesce(op.is_renewal_test_account,false) IS FALSE
  LOOP
    _activity := make_date(_row.year,_row.quarter*3,20+(_row.ordinal%3));
    _release := ((_activity-2)::timestamp + interval '9 hours') AT TIME ZONE 'Asia/Manila';
    UPDATE public.budget_requests br SET
      activity_date=_activity,fiscal_year=_row.year,
      created_at=(((_activity-4)::timestamp + interval '9 hours') AT TIME ZONE 'Asia/Manila'),
      release_date=CASE WHEN br.status::text IN ('budget_released','completed') THEN _activity-2 ELSE NULL END,
      go_signal_at=CASE WHEN br.go_signal_at IS NOT NULL THEN _release-interval '2 days'+interval '3 hours' ELSE NULL END,
      hard_copy_submitted_at=CASE WHEN br.hard_copy_submitted_at IS NOT NULL THEN _release-interval '1 day' ELSE NULL END,
      updated_at=clock_timestamp()
    WHERE br.id=_row.id AND br.organization_id=_row.organization_id
      AND br.is_seeded_sample_data IS TRUE AND br.seed_batch='PCYDO-YORP-2024-2026';
    UPDATE public.liquidation_reports lr SET
      created_at=(((_activity+1)::timestamp + interval '9 hours') AT TIME ZONE 'Asia/Manila'),
      go_signal_at=_release,deadline_at=_release+interval '30 days',
      hard_copy_submitted_at=CASE WHEN lr.hard_copy_submitted_at IS NOT NULL THEN _release+interval '9 days' ELSE NULL END,
      completed_at=CASE WHEN lr.completed_at IS NOT NULL THEN _release+interval '12 days' ELSE NULL END,
      updated_at=clock_timestamp()
    WHERE lr.budget_request_id=_row.id AND lr.organization_id=_row.organization_id
      AND lr.is_seeded_sample_data IS TRUE AND lr.seed_batch='PCYDO-YORP-2024-2026';
  END LOOP;
  EXECUTE _terminal_definition;

  SELECT jsonb_agg(jsonb_build_array(br.id,br.organization_id,br.status,br.requested_amount,br.approved_amount,br.released_amount) ORDER BY br.id) INTO _after
  FROM public.budget_requests br JOIN public.organization_profiles op ON op.id=br.organization_id
  WHERE br.is_seeded_sample_data IS TRUE AND br.seed_batch='PCYDO-YORP-2024-2026'
    AND op.is_seeded_sample_data IS TRUE AND op.seed_batch=br.seed_batch
    AND op.id <> '8170959f-2bb8-40ea-8ce8-31deb514de17'::uuid AND coalesce(op.is_renewal_test_account,false) IS FALSE;
  SELECT jsonb_agg(jsonb_build_array(lr.id,lr.budget_request_id,lr.organization_id,lr.status) ORDER BY lr.id) INTO _reports_after
  FROM public.liquidation_reports lr JOIN public.organization_profiles op ON op.id=lr.organization_id
  WHERE lr.is_seeded_sample_data IS TRUE AND lr.seed_batch='PCYDO-YORP-2024-2026'
    AND op.is_seeded_sample_data IS TRUE AND op.seed_batch=lr.seed_batch
    AND op.id <> '8170959f-2bb8-40ea-8ce8-31deb514de17'::uuid AND coalesce(op.is_renewal_test_account,false) IS FALSE;
  IF _before IS DISTINCT FROM _after OR _reports_before IS DISTINCT FROM _reports_after THEN
    RAISE EXCEPTION 'Seed date repair changed financial values, identities or statuses';
  END IF;
  SELECT count(*) INTO _missing FROM (VALUES (2024,1),(2024,2),(2024,3),(2024,4),(2025,1),(2025,2),(2025,3),(2025,4),(2026,1)) periods(year,quarter)
  WHERE NOT EXISTS (SELECT 1 FROM public.budget_requests br
    WHERE br.is_seeded_sample_data IS TRUE AND br.seed_batch='PCYDO-YORP-2024-2026'
      AND br.fiscal_year=periods.year AND extract(quarter FROM br.activity_date)=periods.quarter AND br.released_amount>0);
  IF _missing <> 0 THEN RAISE EXCEPTION 'Missing released-budget coverage in % quarters',_missing; END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.user_replace_document_submission_file(_file_id uuid, _new_file_url text, _new_file_name text, _new_file_type text, _new_file_size numeric DEFAULT NULL::numeric, _submit_for_review boolean DEFAULT true)
 RETURNS document_submission_files
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _old_file record;
  _submission record;
  _owner_id uuid;
  _history jsonb;
  _history_entry jsonb;
  _updated_row public.document_submission_files;
BEGIN
  SELECT * INTO _old_file
  FROM public.document_submission_files
  WHERE id = _file_id;

  IF _old_file.id IS NULL THEN
    RAISE EXCEPTION 'Document file not found.';
  END IF;

  SELECT * INTO _submission
  FROM public.document_submissions
  WHERE id = _old_file.submission_id;

  IF _submission.id IS NULL THEN
    RAISE EXCEPTION 'Parent document submission not found.';
  END IF;

  SELECT user_id INTO _owner_id
  FROM public.organization_profiles
  WHERE id = _submission.organization_id;

  IF _owner_id <> auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this submission.';
  END IF;

  _history_entry := jsonb_build_object(
    'action', 'replaced',
    'previousFileName', _old_file.file_name,
    'previousFileUrl', _old_file.file_url,
    'previousFileType', _old_file.file_type,
    'previousFileSize', _old_file.file_size,
    'previousStatus', _old_file.admin_status,
    'adminRemarks', _old_file.admin_remarks,
    'reviewedAt', _old_file.reviewed_at,
    'replacedAt', clock_timestamp()
  );

  _history := coalesce(_old_file.revision_history, '[]'::jsonb) || jsonb_build_array(_history_entry);

  UPDATE public.document_submission_files
  SET
    file_url = _new_file_url,
    file_name = _new_file_name,
    file_type = _new_file_type,
    file_size = coalesce(_new_file_size, _old_file.file_size),
    admin_status = CASE
      WHEN _submit_for_review THEN 'submitted'::public.document_submission_status
      ELSE 'draft'::public.document_submission_status
    END,
    admin_remarks = NULL,
    reviewed_at = NULL,
    uploaded_at = clock_timestamp(),
    updated_at = clock_timestamp(),
    revision_history = _history
  WHERE id = _file_id
  RETURNING * INTO _updated_row;

  RETURN _updated_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.user_resubmit_renewal(p_renewal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _renewal record;
  _submission record;
  _owner_id uuid;
  _end_date date;
  _now timestamptz := clock_timestamp();
BEGIN
  SELECT * INTO _renewal
  FROM public.organization_renewals
  WHERE id = p_renewal_id
  FOR UPDATE;

  IF _renewal.id IS NULL THEN
    RAISE EXCEPTION 'Renewal application not found.';
  END IF;

  SELECT op.user_id INTO _owner_id
  FROM public.organization_profiles op
  WHERE op.id = _renewal.organization_id;

  IF _owner_id <> auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this organization.';
  END IF;

  IF _renewal.status <> 'needs_revision' THEN
    RAISE EXCEPTION 'Renewal cannot be resubmitted from status "%". Expected "needs_revision".', _renewal.status;
  END IF;

  -- Verify within 180-day window
  SELECT oa.end_date INTO _end_date
  FROM public.organization_accreditations oa
  WHERE oa.id = _renewal.current_accreditation_id;

  IF current_date > (_end_date + 180) THEN
    RAISE EXCEPTION 'Late renewal cutoff has passed (180 days past expiration). Resubmission is no longer allowed.';
  END IF;

  -- Verify all flagged documents have been replaced
  SELECT * INTO _submission
  FROM public.document_submissions
  WHERE renewal_id = p_renewal_id
  FOR UPDATE;

  IF _submission.id IS NULL THEN
    RAISE EXCEPTION 'No document submission packet found for this renewal.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.document_submission_files dsf
    WHERE dsf.submission_id = _submission.id
      AND dsf.admin_status IN ('needs_revision', 'rejected_red')
  ) THEN
    RAISE EXCEPTION 'All documents marked for revision or rejection must be replaced before resubmission.';
  END IF;

  -- Update renewal state to resubmitted
  UPDATE public.organization_renewals
  SET
    status = 'resubmitted',
    updated_at = _now
  WHERE id = p_renewal_id;

  -- Update document submission state
  UPDATE public.document_submissions
  SET
    status = 'submitted',
    updated_at = _now
  WHERE id = _submission.id;

  -- Insert activity log with NULL actor_user_id (org user action)
  INSERT INTO public.activity_logs (
    actor_user_id,
    organization_id,
    action,
    related_type,
    related_id,
    description
  ) VALUES (
    NULL,
    _renewal.organization_id,
    'renewal_resubmitted',
    'renewal',
    p_renewal_id,
    format('Organization resubmitted renewal application for Cycle %s after revisions.', _renewal.cycle_number)
  );

  RETURN jsonb_build_object(
    'success', true,
    'renewal_id', p_renewal_id,
    'resubmitted_at', _now
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.user_start_or_get_renewal_draft(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller_id uuid;
  _profile record;
  _curr_acc record;
  _existing_renewal record;
  _submission record;
  _today date := current_date;
  _end_date date;
  _target_cycle integer;
  _new_renewal record;
  _new_submission record;
BEGIN
  _caller_id := auth.uid();
  IF _caller_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: Authentication required.';
  END IF;

  -- Lock organization profile to serialize draft creation
  SELECT op.id, op.user_id, op.profile_status, op.current_accreditation_id, op.accreditation_expires_at
  INTO _profile
  FROM public.organization_profiles op
  WHERE op.id = p_organization_id
  FOR UPDATE;

  IF _profile.id IS NULL THEN
    RAISE EXCEPTION 'Organization profile not found.';
  END IF;

  IF _profile.user_id <> _caller_id THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this organization.';
  END IF;

  IF _profile.profile_status <> 'verified' THEN
    RAISE EXCEPTION 'Organization must have verified profile status to initiate renewal.';
  END IF;

  -- Resolve authoritative accreditation term
  SELECT oa.*
  INTO _curr_acc
  FROM public.organization_accreditations oa
  WHERE oa.id = _profile.current_accreditation_id
    AND oa.organization_id = p_organization_id
  LIMIT 1;

  IF _curr_acc.id IS NULL THEN
    SELECT oa.*
    INTO _curr_acc
    FROM public.organization_accreditations oa
    WHERE oa.organization_id = p_organization_id
      AND oa.status = 'active'
    ORDER BY oa.term_number DESC
    LIMIT 1;
  END IF;

  IF _curr_acc.id IS NULL THEN
    RAISE EXCEPTION 'No authoritative accreditation term found for this organization.';
  END IF;

  IF _curr_acc.status = 'revoked' THEN
    RAISE EXCEPTION 'Accreditation has been revoked. Organization cannot renew and must contact LYDO.';
  END IF;

  _end_date := _curr_acc.end_date;

  -- Verify renewal window: [end_date - 90 days, end_date + 180 days]
  IF _today < (_end_date - 90) THEN
    RAISE EXCEPTION 'Renewal window is not yet open. Renewals open 90 days prior to expiration (on %).', (_end_date - 90);
  END IF;

  IF _today > (_end_date + 180) THEN
    RAISE EXCEPTION 'Late renewal window has expired (180 days past expiration). Full re-registration is required.';
  END IF;

  -- Check if a non-terminal renewal is already in progress
  SELECT *
  INTO _existing_renewal
  FROM public.organization_renewals
  WHERE organization_id = p_organization_id
    AND status IN ('draft', 'submitted', 'under_review', 'needs_revision', 'resubmitted')
  ORDER BY cycle_number DESC
  LIMIT 1;

  IF _existing_renewal.id IS NOT NULL THEN
    SELECT * INTO _submission
    FROM public.document_submissions
    WHERE renewal_id = _existing_renewal.id
    LIMIT 1;

    RETURN jsonb_build_object(
      'renewal', row_to_json(_existing_renewal),
      'submission', row_to_json(_submission),
      'is_existing', true
    );
  END IF;

  -- Calculate target cycle number (strictly current_term.term_number + 1)
  _target_cycle := _curr_acc.term_number + 1;

  -- Verify no terminal rejected renewal exists for this cycle
  IF EXISTS (
    SELECT 1 FROM public.organization_renewals
    WHERE organization_id = p_organization_id
      AND cycle_number = _target_cycle
      AND status = 'rejected'
  ) THEN
    RAISE EXCEPTION 'Renewal application for Cycle % was rejected. Organization must contact LYDO directly.', _target_cycle;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.organization_renewals
    WHERE organization_id = p_organization_id
      AND cycle_number = _target_cycle
      AND status = 'approved'
  ) THEN
    RAISE EXCEPTION 'Cycle % is already approved.', _target_cycle;
  END IF;

  -- Create single draft renewal application
  INSERT INTO public.organization_renewals (
    organization_id,
    cycle_number,
    current_accreditation_id,
    status
  ) VALUES (
    p_organization_id,
    _target_cycle,
    _curr_acc.id,
    'draft'
  ) RETURNING * INTO _new_renewal;

  -- Create single linked document submission packet
  INSERT INTO public.document_submissions (
    organization_id,
    submitted_by,
    status,
    user_confirmed,
    submission_scope,
    renewal_id
  ) VALUES (
    p_organization_id,
    _caller_id,
    'draft',
    false,
    'renewal',
    _new_renewal.id
  ) RETURNING * INTO _new_submission;

  RETURN jsonb_build_object(
    'renewal', row_to_json(_new_renewal),
    'submission', row_to_json(_new_submission),
    'is_existing', false
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.user_submit_renewal(p_renewal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _renewal record;
  _submission record;
  _owner_id uuid;
  _end_date date;
  _now timestamptz := clock_timestamp();
BEGIN
  SELECT * INTO _renewal
  FROM public.organization_renewals
  WHERE id = p_renewal_id
  FOR UPDATE;

  IF _renewal.id IS NULL THEN
    RAISE EXCEPTION 'Renewal application not found.';
  END IF;

  SELECT op.user_id INTO _owner_id
  FROM public.organization_profiles op
  WHERE op.id = _renewal.organization_id;

  IF _owner_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this organization.';
  END IF;

  IF _renewal.status <> 'draft' THEN
    RAISE EXCEPTION 'Renewal cannot be submitted from status "%". Expected "draft".', _renewal.status;
  END IF;

  SELECT oa.end_date INTO _end_date
  FROM public.organization_accreditations oa
  WHERE oa.id = _renewal.current_accreditation_id;

  IF current_date > (_end_date + 180) THEN
    RAISE EXCEPTION 'Late renewal cutoff has passed (180 days past expiration). Application can no longer be submitted.';
  END IF;

  SELECT * INTO _submission
  FROM public.document_submissions
  WHERE renewal_id = p_renewal_id
  FOR UPDATE;

  IF _submission.id IS NULL THEN
    RAISE EXCEPTION 'No renewal document submission found.';
  END IF;

  -- Each selected document may be sent as it is ready. The admin approval RPC
  -- continues to enforce completeness and approval of every required type.
  IF NOT EXISTS (
    SELECT 1
    FROM public.document_submission_files dsf
    JOIN public.required_document_types rdt ON rdt.id = dsf.document_type_id
    WHERE dsf.submission_id = _submission.id
      AND rdt.is_active = true
      AND coalesce(rdt.is_required, true) = true
      AND rdt.scope IN ('renewal', 'both')
      AND rdt.template_scope = 'document_submission'
      AND nullif(trim(dsf.file_url), '') IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Upload at least one required renewal document before submitting.';
  END IF;

  UPDATE public.organization_renewals
  SET status = 'submitted', submitted_at = _now, updated_at = _now
  WHERE id = p_renewal_id;

  UPDATE public.document_submissions
  SET status = 'submitted', submitted_at = _now, updated_at = _now
  WHERE id = _submission.id;

  INSERT INTO public.activity_logs (
    actor_user_id, organization_id, action, related_type, related_id, description
  ) VALUES (
    NULL,
    _renewal.organization_id,
    'renewal_submitted',
    'renewal',
    p_renewal_id,
    format('Organization submitted renewal documents for Cycle %s.', _renewal.cycle_number)
  );

  RETURN jsonb_build_object(
    'success', true,
    'renewal_id', p_renewal_id,
    'submitted_at', _now
  );
END;
$function$

CREATE OR REPLACE FUNCTION ytrace_identity.authorize_reviewer(_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare _admin uuid; _role text; _permissions text[];
begin
 select s.admin_id,r.code,r.permission_codes into _admin,_role,_permissions
 from public.validate_admin_session_token(_token) s join public.admin_accounts a on a.id=s.admin_id and a.is_active
 join public.roles r on r.id=a.role_id limit 1;
 if _admin is null or (_role<>'super_admin' and not('registrations_management'=any(coalesce(_permissions,array[]::text[])))) then
   raise exception 'An authorized registration reviewer is required.';
 end if;
 return _admin;
end $function$
